/* FishMore.js - the rest of the sea's population, one block per water.

   Same fields as FishData (see the top of that file). Each entry is written
   with F(zone, id, name, rarity, where, water, time, bait, kg, cm, value,
   [power, stamina, erratic, jump], art, blurb, more): `zone` is its ZMIN, the
   depth zone it belongs to. `art.kind` builds something that is not a fish
   at all (squid, crab, ray, jelly...) - see FishArt.

   FishData appends these to FISH, so nothing else needs to know which file
   a species came from. */

const A = (o) => Object.assign({ h: 0.26, w: 0.12, back: 0x5a7a4a, belly: 0xd8d0a8, fin: 0x4a6a3a, pat: 'none', patCol: 0x2a3a2a, tail: 'fork', extras: [] }, o);
export const MORE_ZMIN = {};
const F = (z, id, name, rarity, where, water, time, bait, kg, cm, value, f, art, blurb, more = {}) => {
  MORE_ZMIN[id] = z;
  return { id, name, rarity, where, water, time, bait, kg, cm, value, fight: { power: f[0], stamina: f[1], erratic: f[2], jump: f[3] }, art: A(art), blurb, ...more };
};
